import{_ as n,o as s,c as t,a0 as e}from"./chunks/framework.akKRIpjQ.js";const u=JSON.parse('{"title":"06 · 设置 · 隐私 · 反馈 · 常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/06-settings-faq.md","filePath":"zh/guide/06-settings-faq.md"}'),p={name:"zh/guide/06-settings-faq.md"};function l(o,a,r,i,d,h){return s(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="_06-·-设置-·-隐私-·-反馈-·-常见问题" tabindex="-1">06 · 设置 · 隐私 · 反馈 · 常见问题 <a class="header-anchor" href="#_06-·-设置-·-隐私-·-反馈-·-常见问题" aria-label="Permalink to &quot;06 · 设置 · 隐私 · 反馈 · 常见问题&quot;">​</a></h1><blockquote><p>「我的」Tab 拆解 + FAQ 合集。</p></blockquote><h2 id="「我的」tab-全栏" tabindex="-1">「我的」Tab 全栏 <a class="header-anchor" href="#「我的」tab-全栏" aria-label="Permalink to &quot;「我的」Tab 全栏&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌───────────────────────────────────┐</span></span>
<span class="line"><span>│ 我的                              │</span></span>
<span class="line"><span>├───────────────────────────────────┤</span></span>
<span class="line"><span>│ 外观                              │</span></span>
<span class="line"><span>│  · 主题（跟随 / 浅 / 深 / OLED 黑） │</span></span>
<span class="line"><span>│  · 单位（mm/in, g/oz, lbs/kg）      │</span></span>
<span class="line"><span>│  · 字体大小（标准 / 大）          │</span></span>
<span class="line"><span>├───────────────────────────────────┤</span></span>
<span class="line"><span>│ 数据                              │</span></span>
<span class="line"><span>│  · 导出（JSON / CSV）             │</span></span>
<span class="line"><span>│  · 导入                            │</span></span>
<span class="line"><span>│  · 删除全部数据                    │</span></span>
<span class="line"><span>├───────────────────────────────────┤</span></span>
<span class="line"><span>│ 提醒                              │</span></span>
<span class="line"><span>│  · 换线提醒开关                    │</span></span>
<span class="line"><span>│  · 提醒时间窗（09:00 / 12:00 等） │</span></span>
<span class="line"><span>│  · 启用原图存档（V1.1）         │</span></span>
<span class="line"><span>├───────────────────────────────────┤</span></span>
<span class="line"><span>│ 隐私 &amp; 许可                       │</span></span>
<span class="line"><span>│  · 隐私清单                       │</span></span>
<span class="line"><span>│  · 开源许可（MediaPipe, Fonts）    │</span></span>
<span class="line"><span>│  · 第三方组件                     │</span></span>
<span class="line"><span>├───────────────────────────────────┤</span></span>
<span class="line"><span>│ 反馈                              │</span></span>
<span class="line"><span>│  · 发送反馈                       │</span></span>
<span class="line"><span>├───────────────────────────────────┤</span></span>
<span class="line"><span>│ 关于                              │</span></span>
<span class="line"><span>│  · 版本号（V1.0.x build xxx）    │</span></span>
<span class="line"><span>│  · 应用商店链接                    │</span></span>
<span class="line"><span>└───────────────────────────────────┘</span></span></code></pre></div><h2 id="主题与显示" tabindex="-1">主题与显示 <a class="header-anchor" href="#主题与显示" aria-label="Permalink to &quot;主题与显示&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>选项</th><th>默认</th></tr></thead><tbody><tr><td>主题</td><td>跟随系统 / 浅色 / 深色 / OLED 纯黑（V1.1+）</td><td>跟随系统</td></tr><tr><td>单位</td><td>公制 / 英制 / 双单位并列</td><td>公制</td></tr><tr><td>字体大小</td><td>标准 / 大 / 超大</td><td>标准</td></tr></tbody></table><blockquote><p>OLED 纯黑：把背景换成 <code>#000000</code>，省电、深色模式更纯净。</p></blockquote><h2 id="数据管理" tabindex="-1">数据管理 <a class="header-anchor" href="#数据管理" aria-label="Permalink to &quot;数据管理&quot;">​</a></h2><h3 id="导出-json" tabindex="-1">导出 JSON <a class="header-anchor" href="#导出-json" aria-label="Permalink to &quot;导出 JSON&quot;">​</a></h3><p><code>我的 → 数据管理 → 导出</code> → 选要导出的范围（球拍档案 / 穿线日志 / 握把测算历史 / 全部）→ 生成 <code>.json</code> 文件 → 系统分享面板。</p><blockquote><p>该文件<strong>不加密</strong>，里面就是你的私人数据。请用邮件发给自己、AirDrop 给自己的电脑 / 保存到加密云盘。<strong>别发朋友圈</strong>。</p></blockquote><h3 id="导入-json" tabindex="-1">导入 JSON <a class="header-anchor" href="#导入-json" aria-label="Permalink to &quot;导入 JSON&quot;">​</a></h3><p><code>我的 → 数据管理 → 导入</code> → 选一份 JSON。重复的条目（按 ID 匹配）会被跳过，不会覆盖你现有数据。</p><h3 id="删除全部数据" tabindex="-1">删除全部数据 <a class="header-anchor" href="#删除全部数据" aria-label="Permalink to &quot;删除全部数据&quot;">​</a></h3><p><code>我的 → 数据管理 → 删除全部数据</code>。需要二次确认。</p><blockquote><p>删完不可恢复（虽然前面你要么已经导出，要么就是不要这个数据了）。</p></blockquote><h2 id="通知" tabindex="-1">通知 <a class="header-anchor" href="#通知" aria-label="Permalink to &quot;通知&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td>换线提醒</td><td>开启</td><td>需要系统层允许通知</td></tr><tr><td>提醒时间窗</td><td>09:00</td><td>你可以选 09:00 / 12:00 / 20:00</td></tr><tr><td>提前几天</td><td>提前 3 天</td><td>到期前 3 天、1 天、零天 各推一次</td></tr></tbody></table><p>如果通知被关掉，进系统 <code>设置 → 应用 → AceCrush Craft → 通知</code> 重新开启后回 App 重置。</p><h2 id="隐私-许可" tabindex="-1">隐私 &amp; 许可 <a class="header-anchor" href="#隐私-许可" aria-label="Permalink to &quot;隐私 &amp; 许可&quot;">​</a></h2><h3 id="隐私与权限清单" tabindex="-1">隐私与权限清单 <a class="header-anchor" href="#隐私与权限清单" aria-label="Permalink to &quot;隐私与权限清单&quot;">​</a></h3><table tabindex="0"><thead><tr><th>权限</th><th>何时申请</th><th>用作</th><th>是否可以拒绝</th></tr></thead><tbody><tr><td><strong>通知</strong></td><td>首次启动</td><td>换线提醒</td><td>可以（关了就收不到提醒）</td></tr><tr><td><strong>相机</strong></td><td>V1.1 拍照测握把</td><td>拍手掌</td><td>可以（改用手动校准）</td></tr><tr><td><strong>相册 / 文件</strong></td><td>用户主动「保存到相册」</td><td>导出图</td><td>可以（改用「分享到」流程）</td></tr><tr><td><strong>网络</strong></td><td>第一次需要时</td><td>反馈发送</td><td>关了 → 反馈延迟到开网</td></tr></tbody></table><blockquote><p>这份清单是 V1.0+ 完整权限要求。&quot;网络&quot;权限只在用户<strong>主动发送反馈</strong>时使用，<strong>默认不上传</strong>。</p><p>历史定位 / 通讯录 / 通讯录 / 设备 ID / IMEI —— <strong>全部不申请</strong>。</p></blockquote><h3 id="开源许可" tabindex="-1">开源许可 <a class="header-anchor" href="#开源许可" aria-label="Permalink to &quot;开源许可&quot;">​</a></h3><p>内嵌的 <a href="https://github.com/google-ai-edge/mediapipe" target="_blank" rel="noreferrer">MediaPipe</a> 及其 Pose / Hand 模型都遵循 Apache License 2.0。完整文本在 <code>我的 → 开源许可</code>，打包成 Assets bundle，可离线查看。</p><p>字体使用系统默认（Roboto / SF Pro / PingFang），不打包第三方字体。</p><h3 id="第三方组件" tabindex="-1">第三方组件 <a class="header-anchor" href="#第三方组件" aria-label="Permalink to &quot;第三方组件&quot;">​</a></h3><p>仅含开源依赖（MediaPipe + 一两个 Dart 包）。详细列表见 <code>我的 → 第三方组件</code>。</p><hr><h2 id="反馈" tabindex="-1">反馈 <a class="header-anchor" href="#反馈" aria-label="Permalink to &quot;反馈&quot;">​</a></h2><p><code>我的 → 发送反馈</code>，分类（Bug / 建议 / 其他）+ 文本（最多 2000 字）。</p><p>每条反馈<strong>附带</strong>：</p><ul><li>App 版本号（如 V1.0.2 build 2026-08-30）</li><li>系统版本（Android 14 / API 34）</li><li>设备型号（如 Xiaomi 14）</li><li>屏幕分辨率 / DPI</li><li>反馈提交时刻</li></ul><p><strong>不附带</strong>你的账号、地理位置、相册、握把测算历史等任何私人数据。</p><p>反馈发起后 → 后台工单 → 团队排期内回复。如需更新，App 内 <code>我的 → 反馈历史</code> 看回信。</p><hr><h2 id="常见问题-faq" tabindex="-1">常见问题（FAQ） <a class="header-anchor" href="#常见问题-faq" aria-label="Permalink to &quot;常见问题（FAQ）&quot;">​</a></h2><h3 id="_1-app-是不是完全免费的" tabindex="-1">1. App 是不是完全免费的? <a class="header-anchor" href="#_1-app-是不是完全免费的" aria-label="Permalink to &quot;1. App 是不是完全免费的?&quot;">​</a></h3><p><strong>是</strong>。无广告、无内购、无会员。</p><h3 id="_2-升级到-v1-1-会收费吗" tabindex="-1">2. 升级到 V1.1 会收费吗? <a class="header-anchor" href="#_2-升级到-v1-1-会收费吗" aria-label="Permalink to &quot;2. 升级到 V1.1 会收费吗?&quot;">​</a></h3><p><strong>不会</strong>。</p><h3 id="_3-数据会被上传吗" tabindex="-1">3. 数据会被上传吗? <a class="header-anchor" href="#_3-数据会被上传吗" aria-label="Permalink to &quot;3. 数据会被上传吗?&quot;">​</a></h3><p><strong>不上传</strong>，除非你点 <a href="#反馈">反馈</a>。</p><h3 id="_4-我卸载了-数据恢复不了" tabindex="-1">4. 我卸载了，数据恢复不了？ <a class="header-anchor" href="#_4-我卸载了-数据恢复不了" aria-label="Permalink to &quot;4. 我卸载了，数据恢复不了？&quot;">​</a></h3><p>是的，没云备份——见 <a href="./04-stringing-log.html#删除一支球拍">04 · 数据迁移</a>。</p><h3 id="_5-ios-什么时候有" tabindex="-1">5. iOS 什么时候有? <a class="header-anchor" href="#_5-ios-什么时候有" aria-label="Permalink to &quot;5. iOS 什么时候有?&quot;">​</a></h3><p>暂无可用版本。详见 <a href="./00-introduction.html#支持平台">00 · 支持平台</a>。</p><h3 id="_6-启动后空白-卡死怎么办" tabindex="-1">6. 启动后空白 / 卡死怎么办? <a class="header-anchor" href="#_6-启动后空白-卡死怎么办" aria-label="Permalink to &quot;6. 启动后空白 / 卡死怎么办?&quot;">​</a></h3><ol><li>重启 App</li><li>若仍异常：<code>我的 → 数据管理 → 删除全部数据</code>（先把 JSON 导出）</li><li>还不行：卸载重装</li></ol><h3 id="_7-怎么把-app-图标放到桌面" tabindex="-1">7. 怎么把 App 图标放到桌面? <a class="header-anchor" href="#_7-怎么把-app-图标放到桌面" aria-label="Permalink to &quot;7. 怎么把 App 图标放到桌面?&quot;">​</a></h3><p>Android 安装后桌面会有图标。长按拖到文件夹里也行。</p><h3 id="_8-我用了第三方启动器-如-nova-图标不一样" tabindex="-1">8. 我用了第三方启动器（如 Nova），图标不一样？ <a class="header-anchor" href="#_8-我用了第三方启动器-如-nova-图标不一样" aria-label="Permalink to &quot;8. 我用了第三方启动器（如 Nova），图标不一样？&quot;">​</a></h3><p>Android 自适应图标在你启动器里可能渲染为不同形状，但功能不影响。</p><h3 id="_9-可以导出为-pdf-excel-吗" tabindex="-1">9. 可以导出为 PDF / Excel 吗? <a class="header-anchor" href="#_9-可以导出为-pdf-excel-吗" aria-label="Permalink to &quot;9. 可以导出为 PDF / Excel 吗?&quot;">​</a></h3><p>V1.0 仅 JSON 导出。V1.1 起会加 CSV（适合 Excel）。</p><h3 id="_10-我能贡献翻译吗" tabindex="-1">10. 我能贡献翻译吗? <a class="header-anchor" href="#_10-我能贡献翻译吗" aria-label="Permalink to &quot;10. 我能贡献翻译吗?&quot;">​</a></h3><p>暂未开放翻译协作。V1.0 起官方语言：简体中文 / English。</p><h3 id="_11-这个项目会开源吗" tabindex="-1">11. 这个项目会开源吗? <a class="header-anchor" href="#_11-这个项目会开源吗" aria-label="Permalink to &quot;11. 这个项目会开源吗?&quot;">​</a></h3><p><a href="./00-introduction.html#当前不-做的事">V1.0 上架后另行评估</a>。当前不提供源代码 / 二进制构建脚本。</p><h3 id="_12-我在测试中遇到-bug-怎么报告" tabindex="-1">12. 我在测试中遇到 Bug，怎么报告? <a class="header-anchor" href="#_12-我在测试中遇到-bug-怎么报告" aria-label="Permalink to &quot;12. 我在测试中遇到 Bug，怎么报告?&quot;">​</a></h3><p><strong>最快</strong>：App 内 <code>我的 → 发送反馈</code>。 <strong>邮件</strong>：<a href="mailto:support@acecrush.dev" target="_blank" rel="noreferrer">support@acecrush.dev</a>（含日志截图）。</p><h3 id="_13-ios-safari-链接到-app-会失败吗" tabindex="-1">13. iOS Safari 链接到 App 会失败吗? <a class="header-anchor" href="#_13-ios-safari-链接到-app-会失败吗" aria-label="Permalink to &quot;13. iOS Safari 链接到 App 会失败吗?&quot;">​</a></h3><p><strong>会</strong>。当前没有 iOS 版本，Universal Links 也没配置——直接打开官网即可。</p><hr><h2 id="报告-bug-模板" tabindex="-1">报告 Bug 模板 <a class="header-anchor" href="#报告-bug-模板" aria-label="Permalink to &quot;报告 Bug 模板&quot;">​</a></h2><p>如果你要发邮件，手动抄送以下信息会加速排查：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>App 版本: V1.0.x build xxx</span></span>
<span class="line"><span>设备: &lt;型号 + Android 版本&gt;</span></span>
<span class="line"><span>复现步骤:</span></span>
<span class="line"><span>  1. ...</span></span>
<span class="line"><span>  2. ...</span></span>
<span class="line"><span>期望行为:</span></span>
<span class="line"><span>实际行为:</span></span>
<span class="line"><span>截图: &lt;附件&gt;</span></span>
<span class="line"><span>日志: &lt;从手机文件管理 / Android/data/com.acecrushcraft.app/files/logs 取 .log&gt;</span></span></code></pre></div><h2 id="联系" tabindex="-1">联系 <a class="header-anchor" href="#联系" aria-label="Permalink to &quot;联系&quot;">​</a></h2><ul><li>邮箱：<a href="mailto:support@acecrush.dev" target="_blank" rel="noreferrer">support@acecrush.dev</a></li><li>小红书：<code>@AceCrush</code></li></ul><blockquote><p>邮件通常 1–3 个工作日内回复。小红书评论不是反馈渠道。</p></blockquote>`,70)])])}const b=n(p,[["render",l]]);export{u as __pageData,b as default};
